package dev.emanoel.shopcore.config;
import dev.emanoel.shopcore.category.*; import dev.emanoel.shopcore.user.*; import org.springframework.boot.CommandLineRunner; import org.springframework.context.annotation.*; import org.springframework.security.crypto.password.PasswordEncoder;
@Configuration public class DataSeeder { @Bean CommandLineRunner seed(UserRepository users,CategoryRepository categories,PasswordEncoder encoder){return args->{if(!users.existsByEmailIgnoreCase("admin@shopcore.dev"))users.save(new User("Shopcore Admin","admin@shopcore.dev",encoder.encode("Admin123!"),Role.ADMIN));if(!categories.existsByNameIgnoreCase("Electronics"))categories.save(new Category("Electronics"));if(!categories.existsByNameIgnoreCase("Books"))categories.save(new Category("Books"));};} }
